module fastc

import os
import v.cmdexec

// A constant initializer calling an imported generic function
// (`vsync.new_tls[voidptr](...)`) gets that instance generated by the declaring file.
fn test_fastc_constant_initializer_instantiates_imported_generic() {
	$if !macos && !linux {
		return
	}
	root := os.join_path(os.vtmp_dir(), 'fastc_constant_initializer_instantiates_import_${os.getpid()}')
	os.mkdir_all(root) or { panic(err) }
	defer {
		os.rmdir_all(root) or {}
	}
	os.write_file(os.join_path(root, 'main.v'), "module main

import sync as vsync

const storage = $if wasm32_wasi {
	unsafe { nil }
} $else {
	vsync.new_tls[voidptr](unsafe { nil }) or { panic(err) }
}

fn kind[T](value T) string {
	$if T in [i8, i16, int, $float] {
		return 'number'
	} $else $if T !in [string, bool] {
		return 'other'
	}
	return 'text or bool'
}

fn main() {
	_ := storage
	println('created')
	vsync.new_tls[string]('x') or { println(err.msg()) }
	println(kind(3))
	println(kind(2.5))
	println(kind('s'))
	println(kind(true))
	println(kind(u64(1)))
}
") or { panic(err) }
	program := os.join_path(root, 'program')
	build := cmdexec.run_in_merged_with_env(@VEXE, ['-b', 'fastc', '-nocache', '-gc', 'none', '-o',
		program, root], os.real_path(os.join_path(@DIR, '../../../..')), {
		'VEXE':                   @VEXE
		'VFLAGS':                 ''
		'VOSARGS':                ''
		'V_MACOS_V3_NO_FALLBACK': '1'
	})
	assert build.exit_code == 0, build.output
	run := cmdexec.run(program, [])
	assert run.exit_code == 0, run.output
	assert run.output.trim_space() == 'created\nnew_tls: invalid type string\nnumber\nnumber\ntext or bool\ntext or bool\nother', run.output
}
